/* assert() without newlib's stdio: its default reports through fiprintf,
 * which drags the whole FILE layer into the image. A failed assertion stops
 * RF and hangs until the independent watchdog resets the board -- where
 * newlib's abort() path ended up too, minus the RF stop. */
void BOARD_EmergencyStop(void);
void __assert_func(const char *file, int line, const char *func, const char *expr)
{
  (void)file;
  (void)line;
  (void)func;
  (void)expr;
  __asm volatile ("cpsid i" ::: "memory");
  BOARD_EmergencyStop();
  while (1) {}
}

/* What newlib would link besides the formatter (the image is linked with
 * -nostartfiles):
 * - crt0's exit() pulled in the stdio FILE layer -- __sf, three FILEs of
 *   312 bytes, the fflush/fwalk walker and newlib's malloc behind them --
 *   only to flush streams nothing opens. The startup file calls main
 *   directly and main never returns, so there is no crt0; __libc_init_array
 *   still runs the constructors and needs these two.
 * - snprintf/vsnprintf into a caller's buffer never grow it (that is
 *   asprintf), yet the formatter references the heap; nothing else here
 *   allocates (ST's PD core goes through --wrap=malloc, radio_pd.c). Asking
 *   for memory returns NULL, which newlib reports as ENOMEM.
 * - The formatter's reentrancy block, without the stdin/stdout/stderr
 *   pointers that would keep __sf: snprintf uses only its errno. */
void _init(void) {}
void _fini(void) {}

