/* newlib's sinf, cosf and tanf reduce |x| up to 2^7 pi/2 (~201) themselves
 * and call this -- 1.7 KB of code with its tables -- only past that. No
 * caller here gets there: every argument is a 2 pi f / fs step, a phase
 * wrapped at 2 pi, a residual of atan2 or a window position. So this stands
 * in for it: the argument, rebuilt from newlib's three 8-bit chunks, reduced
 * by fmodf (in the image anyway) against 2 pi in float. Checked on cm4emu
 * with newlib's own sinf/cosf: identical up to 200 rad, 3e-6 off at 202 rad
 * and 2.4e-4 at 12,345 rad -- degraded, not wrong, where the table-driven
 * reduction was exact at any size. */
int __kernel_rem_pio2f(float *x, float *y, int e0, int nx, int prec, const int32_t *ipio2)
{
  (void)prec;
  (void)ipio2;
  float v = 0.0f;
  for (int i = nx - 1; i >= 0; --i) v = v * (1.0f / 256.0f) + x[i];
  const uint32_t bits = (uint32_t)(127 + e0) << 23; /* 2^e0; e0 is 0..120 on this path */
  float scale;
  memcpy(&scale, &bits, sizeof(scale));
  v = fmodf(v * scale, 6.28318530718f);
  const int n = (int)(v * 0.636619772f); /* quadrant 0..3 */
  y[0] = v - (float)n * 1.57079632679f;
  y[1] = 0.0f;
  return n;
}

/* newlib's __ieee754_rem_pio2f (libm/math/ef_rem_pio2.c), which sinf, cosf
 * and tanf call past pi/4, as it is but for one thing: the 792-byte
 * two_over_pi table it only hands to __kernel_rem_pio2f, which the stub
 * above never reads. Every result is the one newlib's object gave.
 *
 * ====================================================
 * Copyright (C) 1993 by Sun Microsystems, Inc. All rights reserved.
 *
 * Developed at SunPro, a Sun Microsystems, Inc. business.
 * Permission to use, copy, modify, and distribute this
 * software is freely granted, provided that this notice
 * is preserved.
 * ====================================================
 * Conversion to float by Ian Lance Taylor, Cygnus Support, ian@cygnus.com.
 */
static int32_t float_word(float f) { int32_t w; memcpy(&w, &f, sizeof(w)); return w; }

int32_t __ieee754_rem_pio2f(float x, float *y)
{
  /* The single-precision n * pi/2 with the last 8 bits forced to 0. */
  static const int32_t npio2_hw[] = {
    0x3fc90f00, 0x40490f00, 0x4096cb00, 0x40c90f00, 0x40fb5300, 0x4116cb00,
    0x412fed00, 0x41490f00, 0x41623100, 0x417b5300, 0x418a3a00, 0x4196cb00,
    0x41a35c00, 0x41afed00, 0x41bc7e00, 0x41c90f00, 0x41d5a000, 0x41e23100,
    0x41eec200, 0x41fb5300, 0x4203f200, 0x420a3a00, 0x42108300, 0x4216cb00,
    0x421d1400, 0x42235c00, 0x4229a500, 0x422fed00, 0x42363600, 0x423c7e00,
    0x4242c700, 0x42490f00
  };
  static const float
    two8    = 2.5600000000e+02f, /* 0x43800000 */
    invpio2 = 6.3661980629e-01f, /* 0x3f22f984 */
    pio2_1  = 1.5707855225e+00f, /* 0x3fc90f80, first 17 bits of pi/2 */
    pio2_1t = 1.0804334124e-05f, /* 0x37354443, pi/2 - pio2_1 */
    pio2_2  = 1.0804273188e-05f, /* 0x37354400, second 17 bits */
    pio2_2t = 6.0770999344e-11f, /* 0x2e85a308, pi/2 - (pio2_1 + pio2_2) */
    pio2_3  = 6.0770943833e-11f, /* 0x2e85a300, third 17 bits */
    pio2_3t = 6.1232342629e-17f; /* 0x248d3132, pi/2 - (pio2_1 + pio2_2 + pio2_3) */
  float z, w, t, r, fn;
  float tx[3];
  int32_t i, j, n;
  const int32_t hx = float_word(x), ix = hx & 0x7fffffff;
  int e0, nx;

  if (ix <= 0x3f490fd8) { y[0] = x; y[1] = 0; return 0; } /* |x| ~<= pi/4 */
  if (ix < 0x4016cbe4) {                                  /* |x| < 3pi/4: n = +-1 */
    if (hx > 0) {
      z = x - pio2_1;
      if ((ix & 0xfffffff0) != 0x3fc90fd0) { y[0] = z - pio2_1t; y[1] = (z - y[0]) - pio2_1t; }
      else { z -= pio2_2; y[0] = z - pio2_2t; y[1] = (z - y[0]) - pio2_2t; }
      return 1;
    }
    z = x + pio2_1;
    if ((ix & 0xfffffff0) != 0x3fc90fd0) { y[0] = z + pio2_1t; y[1] = (z - y[0]) + pio2_1t; }
    else { z += pio2_2; y[0] = z + pio2_2t; y[1] = (z - y[0]) + pio2_2t; }
    return -1;
  }
  if (ix <= 0x43490f80) {                                 /* |x| ~<= 2^7 pi/2 */
    t = fabsf(x);
    n = (int32_t)(t * invpio2 + 0.5f);
    fn = (float)n;
    r = t - fn * pio2_1;
    w = fn * pio2_1t;                                     /* good to 40 bits */
    if (n < 32 && (ix & (int32_t)0xffffff00) != npio2_hw[n - 1]) {
      y[0] = r - w;                                       /* no cancellation */
    } else {
      j = ix >> 23;
      y[0] = r - w;
      i = j - ((float_word(y[0]) >> 23) & 0xff);
      if (i > 8) {                                        /* second round, 57 bits */
        t = r; w = fn * pio2_2; r = t - w; w = fn * pio2_2t - ((t - r) - w); y[0] = r - w;
        i = j - ((float_word(y[0]) >> 23) & 0xff);
        if (i > 25) {                                     /* third round, 74 bits */
          t = r; w = fn * pio2_3; r = t - w; w = fn * pio2_3t - ((t - r) - w); y[0] = r - w;
        }
      }
    }
    y[1] = (r - y[0]) - w;
    if (hx < 0) { y[0] = -y[0]; y[1] = -y[1]; return -n; }
    return n;
  }
  if (ix >= 0x7f800000) { y[0] = y[1] = x - x; return 0; } /* inf or NaN */
  e0 = (int)((ix >> 23) - 134);                           /* z = |x| scaled to 2^7 */
  const int32_t zw = ix - ((int32_t)e0 << 23);
  memcpy(&z, &zw, sizeof(z));
  for (i = 0; i < 2; i++) {
    tx[i] = (float)((int32_t)(z));
    z = (z - tx[i]) * two8;
  }
  tx[2] = z;
  nx = 3;
  while (tx[nx - 1] == 0.0f) nx--;
  n = __kernel_rem_pio2f(tx, y, e0, nx, 2, NULL);
  if (hx < 0) { y[0] = -y[0]; y[1] = -y[1]; return -n; }
  return n;
}

__attribute__((weak)) int _read(int file, char *ptr, int len)
{
  (void)file;
  int DataIdx;

  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    *ptr++ = __io_getchar();
  }

  return len;
}

__attribute__((weak)) int _write(int file, char *ptr, int len)
{
  (void)file;
  int DataIdx;

  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    __io_putchar(*ptr++);
  }
  return len;
}

